<?php require_once 'bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)$error='Use a name, valid email and password of at least 10 characters.';else{try{$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user_id']=db()->lastInsertId();header('Location: account.php');exit;}catch(PDOException $e){$error='That email address is already registered.';}}}$pageTitle='Create Account | PC World Geek';require 'header.php';?><main class="page"><div class="wrap narrow"><span class="eyebrow">CUSTOMER ACCOUNT</span><h1>Create your account.</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><form class="booking-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Name<input required name="name" autocomplete="name"></label><label>Email<input required type="email" name="email" autocomplete="email"></label><label>Password<input required type="password" name="password" minlength="10" autocomplete="new-password"></label><button class="btn primary">Create Account →</button></form></div></main><?php require 'footer.php';?>